// Extract message from Teams webhook
const body = $input.item.json.body;
const message = {
  text: body.text || '',
  from: {
    id: body.from?.id || '',
    name: body.from?.name || '',
    aadObjectId: body.from?.aadObjectId || ''
  },
  conversation: {
    id: body.conversation?.id || '',
    conversationType: body.conversation?.conversationType || 'personal'
  },
  channelId: body.channelData?.channel?.id || '',
  serviceUrl: body.serviceUrl || '',
  timestamp: new Date().toISOString()
};

return { json: message };

// Get workflow IDs for tools
const workflows = await this.helpers.request({
  method: 'GET',
  url: 'http://localhost:5678/api/v1/workflows',
  headers: {
    'Accept': 'application/json'
  }
});

const workflowMap = {};
workflows.data.forEach(wf => {
  if (wf.name === 'MS Teams Bot - BMS API Caller') {
    workflowMap.bmsCallerId = wf.id;
  } else if (wf.name === 'MS Teams Bot - Context Manager') {
    workflowMap.contextManagerId = wf.id;
  } else if (wf.name === 'Similar Query Detector') {
    workflowMap.similarQueryId = wf.id;
  }
});

return { json: workflowMap };

// Store workflow IDs in global context
const workflowMap = $input.item.json;
return [
  { json: { workflowId: workflowMap.bmsCallerId } },
  { json: { workflowId: workflowMap.contextManagerId } },
  { json: { workflowId: workflowMap.similarQueryId } }
];

// Store conversation after agent response
const userMessage = $('Parse Teams Message').item.json.text;
const agentResponse = $json.output;
const conversationId = $('Parse Teams Message').item.json.conversation.id;

await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://localhost:5678/webhook/context-manager',
  body: {
    action: 'store',
    conversationId: conversationId,
    userMessage: userMessage,
    botResponse: agentResponse
  },
  json: true
});

return $input.all();
